import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int c = in.read();
        while (c != -1 && (c < '0' || c > '9')) c = in.read();
        int n = 0;
        while (c >= '0' && c <= '9') { n = n * 10 + (c - '0'); c = in.read(); }
        int[] dp = new int[n + 1];  // dp[col]: largest all-1 square ending at (row, col), rolling over rows
        int answer = 0;
        for (int row = 0; row < n; row++) {
            int diagonal = 0;
            for (int col = 1; col <= n; col++) {
                c = in.read();
                while (c <= ' ') c = in.read();
                int above = dp[col];
                dp[col] = c == '1' ? 1 + Math.min(above, Math.min(dp[col - 1], diagonal)) : 0;
                if (dp[col] > answer) answer = dp[col];
                diagonal = above;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	c, err := reader.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = reader.ReadByte()
	}
	n := 0
	for err == nil && c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, err = reader.ReadByte()
	}
	dp := make([]int32, n+1) // dp[col]: largest all-1 square ending at (row, col), rolling over rows
	var answer int32
	for row := 0; row < n; row++ {
		var diagonal int32
		for col := 1; col <= n; col++ {
			c, _ = reader.ReadByte()
			for c <= ' ' {
				c, _ = reader.ReadByte()
			}
			above := dp[col]
			if c == '1' {
				dp[col] = 1 + min(above, dp[col-1], diagonal)
			} else {
				dp[col] = 0
			}
			answer = max(answer, dp[col])
			diagonal = above
		}
	}
	fmt.Println(answer)
}
